import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Ensure HIP compilation
os.environ.setdefault("CXX", "hipcc")

# Sum reduction over dim=1 for FP32 tensors shaped [B, D1, D2] -> [B, 1, D2]
# Optimized for D1=4096 typical in this benchmark.

hip_src = r"""
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

static inline __device__ float warp_reduce_sum(float val) {
    // Full mask for AMD wavefronts is 64, but HIP warpSize reports correct size.
    // Use shuffle down for generic warpSize.
    for (int offset = warpSize / 2; offset > 0; offset /= 2) {
        val += __shfl_down(val, offset);
    }
    return val;
}

__global__ void sum_dim1_kernel(const float* __restrict__ x,
                               float* __restrict__ out,
                               int B, int D1, int D2) {
    // One block computes one output element: (b, k)
    int k = (int)blockIdx.x;
    int b = (int)blockIdx.y;

    int tid = (int)threadIdx.x;
    // x is contiguous in row-major: ((b * D1 + i) * D2 + k)
    const float* base = x + ( (long)b * D1 * D2 + k );

    float acc = 0.0f;
    // Stride over D1
    for (int i = tid; i < D1; i += (int)blockDim.x) {
        acc += base[(long)i * D2];
    }

    // Reduce within warp
    acc = warp_reduce_sum(acc);

    // Reduce across warps
    __shared__ float warp_sums[32]; // up to 1024 threads
    int lane = tid % warpSize;
    int warp_id = tid / warpSize;
    if (lane == 0) warp_sums[warp_id] = acc;
    __syncthreads();

    float block_sum = 0.0f;
    if (warp_id == 0) {
        int nwarps = (int)(blockDim.x + warpSize - 1) / warpSize;
        block_sum = (lane < nwarps) ? warp_sums[lane] : 0.0f;
        block_sum = warp_reduce_sum(block_sum);
        if (lane == 0) {
            out[(long)b * D2 + k] = block_sum;
        }
    }
}

torch::Tensor sum_dim1_hip(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA/HIP tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(x.dim() == 3, "x must be a 3D tensor [B, D1, D2]");

    auto x_contig = x.contiguous();
    int64_t B = x_contig.size(0);
    int64_t D1 = x_contig.size(1);
    int64_t D2 = x_contig.size(2);

    auto out = torch::empty({B, 1, D2}, x_contig.options());

    const int threads = 256;
    dim3 block(threads);
    dim3 grid((unsigned int)D2, (unsigned int)B, 1);

    hipStream_t stream = at::hip::getDefaultHIPStream();
    hipLaunchKernelGGL(sum_dim1_kernel, grid, block, 0, stream,
                       (const float*)x_contig.data_ptr<float>(),
                       (float*)out.data_ptr<float>(),
                       (int)B, (int)D1, (int)D2);

    return out;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("sum_dim1_hip", &sum_dim1_hip, "sum over dim=1 keepdim (HIP)");
}
"""

sum_dim1_ext = load_inline(
    name="sum_dim1_ext",
    cpp_sources="",
    cuda_sources=hip_src,
    functions=None,
    extra_cuda_cflags=["-O3"],
    with_cuda=True,
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Fast path only for dim=1, keepdim=True, fp32, 3D
        if self.dim == 1 and x.is_cuda and x.dtype == torch.float32 and x.dim() == 3:
            return sum_dim1_ext.sum_dim1_hip(x)
        return torch.sum(x, dim=self.dim, keepdim=True)


def get_inputs():
    batch_size = 128
    dim1 = 4096
    dim2 = 4095
    x = torch.rand(batch_size, dim1, dim2, device="cuda", dtype=torch.float32)
    return [x]


def get_init_inputs():
    reduce_dim = 1
    return [reduce_dim]

import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

